#!/usr/bin/env bash
# bash completion support for a;b $(c) v2.6.0

_a_b___c_() {
  local word cur prev listFiles
  local -a opts
  COMPREPLY=()
  cur="${COMP_WORDS[COMP_CWORD]}"
  prev="${COMP_WORDS[COMP_CWORD-1]}"
  cmd="_"
  opts=()
  listFiles=0

  _a_b___c__complete() {
    local action="$1"; shift
    mapfile -t values < <( a;b $(c) completions complete "${action}" "${@}" )
    for i in "${values[@]}"; do
      opts+=("$i")
    done
  }

  _a_b___c__expand() {
    [ "$cur" != "${cur%\\}" ] && cur="$cur\\"

    # expand ~username type directory specifications
    if [[ "$cur" == \~*/* ]]; then
      # shellcheck disable=SC2086
      eval cur=$cur

    elif [[ "$cur" == \~* ]]; then
      cur=${cur#\~}
      # shellcheck disable=SC2086,SC2207
      COMPREPLY=( $( compgen -P '~' -u $cur ) )
      return ${#COMPREPLY[@]}
    fi
  }

  # shellcheck disable=SC2120
  _a_b___c__file_dir() {
    listFiles=1
    local IFS=$'\t\n' xspec #glob
    _a_b___c__expand || return 0

    if [ "${1:-}" = -d ]; then
      # shellcheck disable=SC2206,SC2207,SC2086
      COMPREPLY=( ${COMPREPLY[@]:-} $( compgen -d -- $cur ) )
      #eval "$glob"    # restore glob setting.
      return 0
    fi

    xspec=${1:+"!*.$1"}	# set only if glob passed in as $1
    # shellcheck disable=SC2206,SC2207
    COMPREPLY=( ${COMPREPLY[@]:-} $( compgen -f -X "$xspec" -- "$cur" )           $( compgen -d -- "$cur" ) )
  }

  __a_b___c_() {
    opts=(-h --help -V --version --workspace auth issue team user project project-update cycle milestone initiative initiative-update label template document completions config schema api markdown)

    if [[ ${cur} == -* || ${COMP_CWORD} -eq 1 ]] ; then
      return 0
    fi
    case "${prev}" in
      -h|--help) opts=() ;;
      -V|--version) opts=() ;;
      --workspace) opts=(); _a_b___c__complete string $(c) ;;
    esac
  }

  __a_b___c__auth() {
    opts=(-h --help --workspace login logout list default token whoami migrate)

    if [[ ${cur} == -* || ${COMP_CWORD} -eq 2 ]] ; then
      return 0
